from typing import List, Optional
from pydantic import BaseModel, Field, EmailStr
from uuid import UUID

class LeadInput(BaseModel):
    """Represents a single lead generated by AI chat."""
    business_name: str
    industry: Optional[str] = None
    email: Optional[EmailStr] = None
    contact_number: Optional[str] = None
    address: Optional[str] = None
    website: Optional[str] = None
    lead_score: Optional[int] = 0


class ChatCompleteRequest(BaseModel):
    """Schema for /leads/chat/complete — promote or cancel."""

    action: str = Field(..., examples=["save", "cancel"], description="Action type")
    log_id: UUID = Field(..., description="Lead Log ID from which to promote leads")
    selected_lead_ids: Optional[List[UUID]] = Field(
        None, description="Specific lead IDs to promote; if empty, promote all leads in log"
    )

    class Config:
        json_schema_extra = {
            "examples": [
                {
                    "action": "save",
                    "log_id": "8e31acba-f23c-43c7-9dfb-e44237782672",
                    "selected_lead_ids": [
                        "c71f9c8a-9de4-4f65-84a7-3f1344ad9b4a",
                        "63a1778a-02da-4f62-8df3-4a37d9d36d71"
                    ]
                },
                {
                    "action": "cancel",
                    "log_id": "8e31acba-f23c-43c7-9dfb-e44237782672"
                }
            ]
        }